{
  "name": "developer-log-summary",
  "version": "1.0.0",
  "private": true,
  "description": "Summarize JSONL developer logs by level",
  "bin": {
    "log-summary": "dist/index.js"
  },
  "scripts": {
    "build": "tsc",
    "test": "npm run build && node --test dist/test/*.test.js"
  },
  "devDependencies": {
    "@types/node": "^22.0.0",
    "typescript": "^5.0.0"
  }
}

#!/usr/bin/env node

import { readFile, read } from "node:fs/promises";
import { stdin } from "node:process";

interface LogRecord {
  level?: unknown;
}

function summarize(input: string): Map<string, number> {
  const counts = new Map<string, number>();
  for (const line of input.split(/\r?\n/)) {
    if (!line.trim()) continue;
    const record = JSON.parse(line) as LogRecord;
    const level = typeof record.level === "string" && record.level.trim()
      ? record.level.trim().toLowerCase()
      : "unknown";
    counts.set(level, (counts.get(level) ?? 0) + 1);
  }
  return counts;
}

async function inputText(path?: string): Promise<string> {
  if (path) return readFile(path, "utf8");
  const chunks: Buffer[] = [];
  for await (const chunk of stdin) chunks.push(Buffer.from(chunk));
  return Buffer.concat(chunks).toString("utf8");
}

async function main(): Promise<void> {
  const path = process.argv[2];
  if (path === "--help" || path === "-h") {
    console.log("Usage: log-summary [JSONL_FILE]");
    console.log("Read JSONL from a file or stdin and summarize records by level.");
    return;
  }

  const counts = summarize(await inputText(path));
  if (counts.size === 0) {
    console.log("No log records found.");
    return;
  }
  for (const [level, count] of counts) console.log(`${level}: ${count}`);
}

main().catch((error: unknown) => {
  const message = error instanceof Error ? error.message : String(error);
  console.error(`Error: ${message}`);
  process.exitCode = 1;
});

export { summarize };

import assert from "node:assert/strict";
import test from "node:test";
import { summarize } from "../src/index";

test("summarizes records by level", () => {
  const result = summarize('{"level":"INFO"}\n{"level":"error"}\n{"level":"info"}');
  assert.deepEqual([...result], [["info", 2], ["error", 1]]);
});

test("counts records without a level as unknown", () => {
  const result = summarize('{"message":"started"}');
  assert.deepEqual([...result], [["unknown", 1]]);
});
